mapper.update:
update T2000_PROXY
set
delegate_id=#{delegateId},
start_dt=#{startDt},
end_dt=#{endDt},
proxy_comment=#{proxyComment},
update_dt=SYSDATE,
del_yn = #{delYn}
where seq_no=#{seqNo}
and abs_id=#{absId}

mapper.select:
SELECT COUNT(1) FROM T2000_PROXY p JOIN T1000_ACCOUNT a ON p.delegate_id = a.account_id JOIN T1000_USER u ON a.user_no = u.user_no
AND p.del_yn = #{delYn}
AND p.abs_id = #{absId}
AND u.user_name LIKE '%' || #{delegateUserName} || '%'
AND p.proxy_comment LIKE '%' || #{proxyComment} || '%'
AND p.seq_no = #{seqNo}
AND p.start_dt >= TO_DATE(#{startDt}, 'YYYY-MM-DD') AND p.start_dt < TO_DATE(#{endDt}, 'YYYY-MM-DD') + 1
AND p.end_dt >= TO_DATE(#{startDt}, 'YYYY-MM-DD') AND p.end_dt < TO_DATE(#{endDt}, 'YYYY-MM-DD') + 1
